### Export a record with proof fields

The compiler has a checked-record mapping for C, C++ and npm. Installed-package acceptance for this mapping is pending. The [fixture](../../tests/fixtures/onboarding/checked-records/CheckedRecords.lean) and [checks](../../tests/checked-records.test.mjs) cover records whose proofs constrain their payload fields:

```lean
namespace CheckedRecords

structure Interval where
  lo : Nat
  hi : Nat
  ordered : lo ≤ hi

def mkInterval (lo hi : Nat) : Option Interval :=
  if h : lo ≤ hi then some ⟨lo, hi, h⟩ else none

def width (value : Interval) : Nat := value.hi - value.lo

end CheckedRecords
```

Select a checked constructor at each input site in `lean-bridge.exports.json`:

```json
{
  "schemaVersion": 1,
  "modules": ["CheckedRecords"],
  "exports": ["CheckedRecords.width"],
  "contracts": {
    "CheckedRecords.width": {
      "parameters": [{
        "ownership": "copy",
        "lifetime": null,
        "refinement": { "constructor": "CheckedRecords.mkInterval" }
      }],
      "result": { "ownership": "copy", "lifetime": null }
    }
  }
}
```

The constructor must take the payload fields by their exact names, order and types, then return `Option` of the exact record. Lean checks its safety and selected-module dependencies. A constructor can normalize accepted values. Selecting different constructors for two parameters of the same record changes each parameter's behavior.

The host passes only payload fields, such as `{ lo: 3n, hi: 10n }` in JavaScript. The private adapter receives a typed payload mirror without the `ordered` proof. It calls `mkInterval` before calling `width`; `none` rejects the call. It never constructs an unchecked `Interval` or supplies a substitute proof. Native public validation and the adapter each own a fresh conversion. A Lean-produced result already has its proofs, so the adapter returns only its payload and needs no constructor selection at that result site.

Closed natural-number indices use aliases such as `abbrev Triple := Sized 3`, where `Sized` stores `data : Array Nat` and a proof `data.size = n`. A checked constructor takes `data` and returns `Option Triple`. The host record has only `data`; the index `3` remains in authenticated type metadata. A package can export only `Nat → Triple` without having a checked input anywhere.

For a reviewed API, record erased proof names in the type's `lean-lang.org/erased-proofs` extension, and select `{ "kind": "checked-record", "constructor": "CheckedRecords.mkInterval" }` in the declaration's parameter refinement. A closed `Nat` index appears as `{ "kind": "value", "type": { "kind": "primitive", "name": "nat" }, "value": "3" }` in `lean-lang.org/instantiation`. The [independent review fixture](../../tests/helpers/checked-record-fixture.mjs) shows the complete form. Fresh Lean must reproduce the payload layout, erased names, indices and selected constructor. Configuration contracts cannot override a review.

This mapping currently requires a nonempty, closed copied payload at a top-level parameter or result. Nested checked records, value-dependent runtime fields, recursive checked records, other index kinds, callbacks and other target packages remain unsupported. npm uses private ABI 8 for its proof-free carriers. Those implementation checks do not establish installed C/C++ or JavaScript/TypeScript acceptance.

// A checked record's erased proof names are part of its private identity; only the recursive
// graph ABI, whose generated carriers hold payload mirrors, admits them.
const erased = type.kind === "record" ? type.source?.extensions?.["lean-lang.org/erased-proofs"]?.fields : undefined;
return type.kind === "record" ? { kind: "record", id: type.id, fields: fields(type.fields), ...(erased ? { erased: [...erased] } : {}) }

if(kind === "record")
{
	if(!Object.hasOwn(value, "erased")) return Object.freeze({ kind, id: value.id, fields: fields(value.fields) });
	// Erased proof fields are named once, never carried, and disjoint from the payload.
	dense(value.erased, 1024);
	const payload = fields(value.fields);
	if(!value.erased.length || !payload.length || new Set(value.erased).size !== value.erased.length
		|| value.erased.some(item => typeof item !== "string" || !name.test(item) || payload.some(field => field.name === item))) invalid("invalid erased proof fields");
	return Object.freeze({ kind, id: value.id, fields: payload, erased: Object.freeze([...value.erased]) });
}

	return;
}
if(refinement.kind === "checked-record")
{
	// A site's checked constructor builds a record with erased proofs from its payload.
	keys(["kind", "constructor"]);
	if(depth !== 0 || type?.kind !== "named" || typeof refinement.constructor !== "string"
		|| !/^[A-Za-z][A-Za-z0-9_]*(\.[A-Za-z][A-Za-z0-9_]*)*$/.test(refinement.constructor)) fail();

-- A checked record's site keeps its predicate around the inlined record.
if kind == "refinement" && (value.getObjVal? "base" |>.toOption |>.bind fun base => base.getObjValAs? String "kind" |>.toOption) == some "reference" then
  return value.setObjVal! "base" (← inlineCopiedType types (← ofExcept <| value.getObjVal? "base") seen (depth + 1))

// A checked record is built only by its site's constructor; its base is the record itself.
if(type.predicate?.kind === "checked-record")
{
	closed(type.predicate, ["kind", "constructor"]);
	if(typeof type.predicate.constructor !== "string" || !/^[A-Za-z][A-Za-z0-9_]*(\.[A-Za-z][A-Za-z0-9_]*)*$/.test(type.predicate.constructor)
		|| type.base?.kind !== "record" || !Object.hasOwn(type.base, "erased")) fail("Invalid checked record refinement");
	copied(type.base, depth, references, refinements);
	return;
}

closed(type, ["kind", "name", "fields", ...["provenance", "erased"].filter(key => Object.hasOwn(type, key))]);
// Erased proof fields are named once, never cross, and appear only at a top-level site.
if(Object.hasOwn(type, "erased") && (depth !== 0 || !Array.isArray(type.erased) || !type.erased.length || type.erased.length > 1024
	|| new Set(type.erased).size !== type.erased.length || type.erased.some(name => !text(name) || !/^[A-Za-z_][A-Za-z0-9_']*$/.test(name))
	|| !Array.isArray(type.fields) || !type.fields.length || type.fields.some(field => type.erased.includes(field?.name)))) fail("Invalid checked record");

// A value index is provenance only: a closed Nat literal, never a host type.
if(argument?.kind === "value")
{
	closed(argument, ["kind", "type", "value"]);
	closed(argument.type, ["kind", "name"]);
	if(argument.type.kind !== "primitive" || argument.type.name !== "nat" || typeof argument.value !== "string"
		|| !/^(?:0|[1-9][0-9]*)$/.test(argument.value)) fail("Invalid component record value argument");
	continue;
}

if(type.predicate?.kind === "checked-record")
{
	// Only the site's checked constructor builds a record with proof fields, at a top-level parameter.
	if(depth !== 0 || copied || site === "result") fail("checked records require a top-level native parameter constructor");
	closed(type.predicate, ["kind", "constructor"], "refinement predicate");
	if(typeof type.predicate.constructor !== "string" || !identifier.test(type.predicate.constructor)) fail("invalid checked record constructor");
	if(type.base?.kind !== "record" || !Object.hasOwn(type.base, "erased")) fail("checked record refinements require a record with erased proofs");
	validate(type.base, depth, copied, references, policy, owned, structural, "checked-record");
}
else if(type.predicate?.kind === "subtype")

// A value index is provenance only: a closed Nat literal, never a host type.
if(child?.kind === "value")
{
	closed(child, ["kind", "type", "value"], "record value argument");
	recurse(child.type, true, false);
	if(child.type.kind !== "primitive" || child.type.name !== "nat" || typeof child.value !== "string" || !/^(?:0|[1-9][0-9]*)$/.test(child.value)) fail("invalid record value argument");
	continue;
}

// Erased proof fields never cross. A record carrying them crosses only as a Lean-produced
// top-level result or as the base of a parameter's checked-record refinement.
if(Object.hasOwn(type, "erased"))
{
	// A bare one at a parameter would bypass the constructor; representation checks pass no site.
	if(depth !== 0 || copied || references || site === "parameter") fail("checked records cross only through a parameter constructor or as a result");
	if(!Array.isArray(type.erased) || !type.erased.length || type.erased.length > 1024 || new Set(type.erased).size !== type.erased.length
		|| type.erased.some(name => typeof name !== "string" || !/^[A-Za-z_][A-Za-z0-9_']*$/.test(name))
		|| !type.fields.length || type.fields.some(field => type.erased.includes(field.name))) fail("invalid erased proof fields");
}

value.arguments.forEach((argument, index) => {
	// A value index is provenance only: a closed Nat literal, never a host type.
	if(argument?.kind === "value")
	{
		if(!keys(argument, ["kind", "type", "value"]) || !keys(argument.type, ["kind", "name"]) || argument.type.kind !== "primitive"
			|| argument.type.name !== "nat" || typeof argument.value !== "string" || !/^(?:0|[1-9][0-9]*)$/.test(argument.value))
			refuse(`${base}.arguments[${index}]`, "a value argument is a closed Nat literal");
		return;
	}
	reach(argument, `${base}.arguments[${index}]`, 0, "an instantiation argument cannot reach a Fin bound");
});

	// A checked record names its erased proof fields once; the payload stays the record's fields.
	if(Object.hasOwn(definition.source.extensions, erasedProofsKey))
	{
		const erased = definition.source.extensions[erasedProofsKey];
		reject(!erased || typeof erased !== "object" || Array.isArray(erased) || Object.keys(erased).join() !== "fields"
			|| !Array.isArray(erased.fields) || !erased.fields.length || erased.fields.length > 1024 || new Set(erased.fields).size !== erased.fields.length
			|| erased.fields.some(name => typeof name !== "string" || !/^[A-Za-z_][A-Za-z0-9_']*$/.test(name) || definition.fields.some(field => field.name === name))
			|| !definition.fields.length, `${definition.id}.source.extensions.${erasedProofsKey}`);
	}
}
// A checked record crosses only at a top-level site: a parameter through its checked constructor,
// or a Lean-produced result with no constructor.
const checkedRecord = type => type?.kind === "named" && Object.hasOwn(definitions.get(type.id)?.source.extensions ?? {}, erasedProofsKey);
for(const declaration of document.declarations)
{
	const refinements = declaration.source.extensions["lean-lang.org/refinements"];
	for(const [index, value] of declaration.parameters.entries())
		reject(checkedRecord(value.type) !== (refinements?.parameters?.[index]?.kind === "checked-record"), `${declaration.id}.parameters[${index}]`);
	reject(refinements?.result?.kind === "checked-record", `${declaration.id}.result`);

// A Subtype or checked-record constructor is selected per site, over a copied value.
const constructed = ["subtype", "checked-record"].includes(refinement?.kind);
if(constructed && (site.ownership !== "copy" || site.lifetime !== null)) fail();

	definition.source.extensions["lean-lang.org/instantiation"] = { structure: type.provenance.structure
		, arguments: type.provenance.arguments.map(argument => argument.kind === "value" ? { kind: "value", type: reference(argument.type), value: argument.value } : reference(argument)) };
// Proof fields are named, never carried: only a site's checked constructor builds them.
if(type.kind === "record" && type.erased) definition.source.extensions["lean-lang.org/erased-proofs"] = { fields: [...type.erased] };

// Checked records have generated mirror carriers only for C, C++ and npm packages so far.
if([...value.parameters, value.result].some(refinement => refinement?.kind === "checked-record"))
	throw new TypeError(`${declaration.id}: checked records are implemented only for C, C++ and npm packages`);

// Checked records cross only as payload mirrors, which the recursive graph carriers generate.
if(document.types.some(type => Object.hasOwn(type.source?.extensions ?? {}, "lean-lang.org/erased-proofs")))
{
	if(callbackTypes.length) throw new TypeError("Checked records cannot share a component with callbacks yet");
	const exports = document.declarations.map(declaration => ({ bindingId: declaration.id
		, symbol: `lean_bridge_${sha256(`${document.component.id}\0${declaration.id}`).slice(0, 24)}`
		, parameters: declaration.parameters.map(parameter => parameter.type)
		, result: declaration.result.type
		, resultMode: declaration.resultMode }));
	const graph = { version: componentRecursiveAbi, dispatch: componentRecursiveDispatch, types: componentRecordDefinitions(document, true), exports };
	assertComponentRecursiveBindings(graph, document);
	return graph;
}

// A checked record crosses as its payload mirror: carriers build and read only the mirror, and
// each site's constructor alone builds the source record from it.
const checkedRecords = new Map(abi.types.filter(type => type.kind === "record" && type.erased).map(type => [type.id, type]));
const mirror = type => type.kind === "named" && checkedRecords.has(type.id) ? `LbErased.${type.id.slice(5)}` : null;

const sites = exports.map(item => {
	const signature = abi.exports.find(value => value.bindingId === item.bindingId);
	if(!signature) throw new TypeError("Missing recursive export signature");
	const parameters = (item.refinements?.parameters ?? signature.parameters.map(() => null)).map((refinement, index) => refinement?.kind === "checked-record"
		? { ...refinement, definition: signature.parameters[index].id.slice(5) } : refinement);
	const result = mirror(signature.result) ? { kind: "checked-record", definition: signature.result.id.slice(5), constructor: null } : item.refinements?.result ?? null;
	const refinements = parameters.some(Boolean) || result ? { parameters, result } : undefined;
	return { ...item, parameters: item.parameters.map((parameter, index) => mirror(signature.parameters[index]) ? { ...parameter, leanType: mirror(signature.parameters[index]) } : parameter)
		, ...refinements ? { refinements } : {} };
});
for(const [id, type] of checkedRecords)
{
	const name = `LbErased.${id.slice(5)}`, source = `_root_.${id.slice(5)}`, payload = type.fields.map(field => `value.«${field.name}»`).join(" ");
	lines.push(`structure ${name} where`, ...type.fields.map(field => `  «${field.name}» : ${mirror(field.type) ?? sourceType(field.type)}`), ""
		, `def ${name}.erase (value : ${source}) : ${name} :=`, `  ${name}.mk ${payload}`, "");
	const constructors = new Set(sites.flatMap(item => item.refinements?.parameters.filter(refinement => refinement?.kind === "checked-record" && refinement.definition === id.slice(5)).map(refinement => refinement.constructor) ?? []));
	for(const constructor of [...constructors].sort())
		lines.push(`def ${name}.${checkedRecordVia(constructor)} (value : ${name}) : _root_.Option ${source} :=`, `  _root_.${constructor} ${payload}`, "");
}

import { sha256 } from "../capsule/node.mjs";

/**
 * Name the conversion that builds a checked record from its payload mirror with one constructor.
 * Each site chooses its constructor, so a mirror carries one conversion per constructor in use.
 *
 * @param constructor - Fully qualified Lean checked constructor.
 */
export const checkedRecordVia = constructor => `via_${sha256(constructor).slice(0, 16)}`;

// A checked record crosses as its payload mirror: only the site's constructor builds the source
// value, and a Lean-produced one is projected back without any check.
if(refinement.kind === "checked-record")
{
	if(checked && typeof refinement.constructor !== "string") throw new TypeError("A checked record input requires its site's constructor");
	return `(LbErased.${refinement.definition}.${checked ? checkedRecordVia(refinement.constructor) : "erase"} ${input})`;
}

// Checked records cross only as payload mirrors, which only the C and C++ projections generate.
if(refined && model.exports.some(item => [...(item.refinements?.parameters ?? []), item.refinements?.result].some(tree => tree?.kind === "checked-record")) && nativeCheckedRecords !== true)
	throw Object.assign(new TypeError("This native component requires a checked-record consumer adapter"), { code: "native-checked-records-unavailable" });

// Only the site's checked constructor builds a record with erased proofs, from its payload mirror.
if(type.predicate.kind === "checked-record")
{
	if(!top || site !== "parameter") throw unsupported("checked records cross only at a top-level parameter or result");
	return { kind: "checked-record", definition: type.base.lean, constructor: type.predicate.constructor, fields: type.base.fields.map(field => field.name) };
}

// A Lean-produced record with erased proofs is projected to its payload mirror; no constructor runs.
if(type.kind === "record" && Object.hasOwn(type, "erased"))
{
	if(!top || site !== "result") throw unsupported("checked records cross only at a top-level parameter or result");
	return { kind: "checked-record", definition: type.lean, constructor: null, fields: type.fields.map(field => field.name) };
}

// A checked record's mirror holds only its payload. Lean-produced values are projected to it;
// each site's constructor alone builds the source value back from it, so no carrier can.
if(type.kind === "record" && Object.hasOwn(type, "erased"))
{
	lines.push(`structure ${mirror} where`, ...type.fields.map(field => `  «${field.name}» : ${absoluteLeanType(field.type, mirrors)}`), "");
	lines.push(`def ${mirror}.erase (value : ${source}) : ${mirror} :=`
		, `  ${mirror}.mk ${type.fields.map(field => `value.«${field.name}»`).join(" ")}`, "");
	for(const constructor of [...constructors.get(type.lean) ?? []].sort())
		lines.push(`def ${mirror}.${checkedRecordVia(constructor)} (value : ${mirror}) : _root_.Option ${source} :=`
			, `  _root_.${constructor} ${type.fields.map(field => `value.«${field.name}»`).join(" ")}`, "");
	continue;
}

/**
 * Report a document's schema errors, or null when it is valid, for malformed-shape controls.
 *
 * @param reference - Schema filename without the .schema.json suffix, optionally followed by a JSON pointer fragment.
 * @param value - JSON document or fragment.
 */
export const jsonSchemaErrors = async (reference, value) => {
	validatorPromise ??= loadValidator();
	const validator = await validatorPromise;
	const [name, fragment] = reference.split("#");
	const validate = validator.getSchema(`${new URL(`${name}.schema.json`, schemaRoot).href}${fragment === undefined ? "" : `#${fragment}`}`);
	assert.ok(validate, `Missing JSON schema: ${reference}`);
	return validate(value) ? null : validate.errors;
};

test("checked-record guidance uses the tested payload and per-site constructor contract", async () => {
	const document = await readFile("docs/lean/existing-package.md", "utf8");
	const section = document.split("### Export a record with proof fields\n")[1].split("### Export a checked Subtype\n")[0];
	const blocks = fences(section);
	const configuration = JSON.parse(blocks.find(block => block.language === "json").source);
	validateExportConfiguration(configuration);
	assert.deepEqual(configuration.modules, ["CheckedRecords"]);
	assert.deepEqual(configuration.exports, ["CheckedRecords.width"]);
	assert.deepEqual(configuration.contracts, { "CheckedRecords.width": checkedRecordContracts()["CheckedRecords.width"] });
	const example = blocks.find(block => block.language === "lean").source;
	const source = await readFile("tests/fixtures/onboarding/checked-records/CheckedRecords.lean", "utf8");
	for(const declaration of example.trim().split("\n\n")) assert.ok(source.includes(declaration), declaration);
	assert.match(section, /Installed-package acceptance for this mapping is pending/);
	assert.match(section, /exact names, order and types/);
	assert.match(section, /result already has its proofs/);
	assert.match(section, /private ABI 8/);
	assert.match(section, /Configuration contracts cannot override a review/);
	assert.match(await readFile("docs/lean/export-decisions.md", "utf8"), /existing-package.md#export-a-record-with-proof-fields/);
});
